import { LauncherMenu } from './LauncherMenu'
import { Provider } from '@/provider'
import { WebView } from 'react-native-webview'
import { useLauncherState } from './utils/hooks/useLauncherState'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { defineStyles } from '@/utils'

export function LauncherMenuContainer() {
	const insets = useSafeAreaInsets()
	const { state, switchToWeb, switchToMobile } = useLauncherState()
	const projectGroupId: string | null = process.env.EXPO_PUBLIC_PROJECT_GROUP_ID
	if (!projectGroupId) {
		throw new Error('Project group ID is not set')
	}

	return (
		<Provider>
			<LauncherMenu
				devServerHost={null}
				projectGroupId={projectGroupId}
				state={state}
				switchToMobile={switchToMobile}
				switchToWeb={switchToWeb}
			>
				{state.mode === 'web' && (
					<WebView
						source={{
							uri: `${process.env.EXPO_PUBLIC_BASE_URL}${
								state.initialWebPath ?? ''
							}`
						}}
						style={[styles.webView, { paddingTop: insets.top }]}
					/>
				)}
			</LauncherMenu>
		</Provider>
	)
}

const styles = defineStyles({
	webView: {
		flex: 1
	}
})
